$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-detail-l1.mjs'
try {
[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({error:'hard_timeout'}));process.exit(0)},8500);
try{
const v=await(await fetch('http://127.0.0.1:17447/json/version')).json();const w=new WebSocket(v.webSocketDebuggerUrl);
await new Promise((ok,no)=>{w.addEventListener('open',ok,{once:true});w.addEventListener('error',no,{once:true})});
let n=0,p=new Map();w.addEventListener('message',e=>{let z=JSON.parse(e.data);if(p.has(z.id)){p.get(z.id)(z);p.delete(z.id)}});
const send=(method,params)=>Promise.race([new Promise(ok=>{let id=++n;p.set(id,ok);w.send(JSON.stringify({id,method,params}))}),new Promise(ok=>setTimeout(()=>ok({error:{message:'timeout'}}),3500))]);
const a=await send('Target.createTarget',{url:"https://www.avito.ru/krasnoyarsk/telefony/iphone_15_pro_max_512_gb_sim_esim_8107250406",background:true,newWindow:false});const target_id=a.result?.targetId||null;
if(!target_id){console.log(JSON.stringify({error:a.error?.message||'not_created'}));process.exit(0)}
const b=await send('Target.activateTarget',{targetId:target_id});
console.log(JSON.stringify({created:true,activated:!!b.result,target_id,url:"https://www.avito.ru/krasnoyarsk/telefony/iphone_15_pro_max_512_gb_sim_esim_8107250406",error:b.error?.message||null}));process.exit(0);
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,130)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false))
& node.exe $tmp
} finally { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
